import {effectiveTracks,qualityMatches} from './evidence.js?v=1.2.1';
import {placementOf,placementSummary,rankMatches} from './placement.js?v=1.2.1';
let COVERAGE=[];
export let CONFIG={currentCycle:'2026-2027',historyYears:[2023,2024,2025,2026]};
export function configure(config){if(!/^20\d{2}-20\d{2}$/.test(config.currentCycle)||!Array.isArray(config.historyYears)||!config.historyYears.every(Number.isInteger))throw new Error('Invalid archive configuration');CONFIG=config;COVERAGE=config.coverage||[]}
export const REGIONS={US:'United States',CA:'Canada',HK:'Hong Kong',SG:'Singapore',CN:'Mainland China',TW:'Taiwan',MO:'Macao',JP:'Japan',FR:'France',DE:'Germany',ES:'Spain',IT:'Italy',VN:'Vietnam',UY:'Uruguay',IR:'Iran',TR:'Türkiye',UK:'United Kingdom',EU:'Europe',AU:'Australia',KR:'South Korea',IL:'Israel',IN:'India',KW:'Kuwait',PT:'Portugal',NZ:'New Zealand',RU:'Russia',OTHER:'Other regions',UNKNOWN:'Unverified'};
export const JOBS={faculty:'Faculty · tenure status unverified',tt:'Academic faculty · includes inferred cases',non_tt:'Non-tenure-track faculty',postdoc:'Postdoc',industry:'Industry',government:'Government / public agency',research:'Research institution',other:'Industry / other',deferred:'Deferred',unknown:'Job type unverified',on_market:'On the current job market'};
export const BG={all:'All backgrounds',cn_national:'Chinese citizen · publicly confirmed',cn_heritage:'Chinese heritage · self-reported',ug_cn:'Undergraduate degree in Mainland China',ug_hk:'Undergraduate degree in Hong Kong',ug_tw:'Undergraduate degree in Taiwan',ug_other:'Undergraduate degree in another region',ug_unknown:'Undergraduate region unverified'};
export const JOB_COLORS={faculty:'#208b78',tt:'#165c4f',non_tt:'#8eb9ac',postdoc:'#8a94ce',industry:'#d49d56',government:'#617c94',research:'#afbcc4',unknown:'#dfe4e8',on_market:'#829ea0'};
export function backgroundMatches(r,bg){const u=r.undergraduate?.region;if(bg==='all')return true;if(bg==='cn_national')return r.identity?.chinese_national?.value==='yes';if(bg==='cn_heritage')return r.identity?.chinese_heritage?.value==='yes';if(bg==='ug_unknown')return !u||u==='UNKNOWN';if(bg==='ug_other')return !!u&&!['CN','HK','TW','UNKNOWN'].includes(u);return u===({ug_cn:'CN',ug_hk:'HK',ug_tw:'TW'}[bg]);}
export function needsOutcomeReview(r){return r.status==='outcome_unknown'||r.status==='placed'&&!r.placement_year}
export function inArchiveCohort(r){return r.status!=='on_market'&&r.market_cycle!==CONFIG.currentCycle&&[r.source_cohort_year,r.graduation_year,r.placement_year].some(y=>CONFIG.historyYears.includes(y))}
export function recordTime(r,basis){return basis==='source'?r.source_cohort_year:basis==='graduation'?r.graduation_year:basis==='market'?r.market_cycle:basis==='placement'?r.placement_year:null}
export function filterRecords(records,f={}){const words=(f.q||'').toLowerCase().trim().split(/\s+/).filter(Boolean);return records.filter(r=>{const outcome=placementOf(r,f.basis),tracks=effectiveTracks(r,f.researchMode),archive=!f.yearBasis||f.yearBasis==='archive';if(!archive){const t=recordTime(r,f.yearBasis);if(t==null||f.year&&f.year!=='all'&&String(t)!==String(f.year))return false;}if(f.completeOnly==='yes'&&!COVERAGE.some(c=>c.cohort_complete===true&&c.record_ids.includes(r.id)))return false;if(f.tenureEvidence&&f.tenureEvidence!=='all'&&outcome.tenure_evidence_status!==f.tenureEvidence)return false;if(!qualityMatches(r,f.quality))return false;if(!rankMatches(r,f.rank))return false;if(f.material==='jmp'&&!r.jmp)return false;if(f.material==='homepage'&&!r.homepage)return false;if(f.material==='cv'&&!r.cv_url)return false;if(f.scope==='target'&&!r.target_scope)return false;if(f.scope==='io'&&!r.io_scope)return false;if(f.scope==='extension'&&r.target_scope)return false;if(archive&&f.period==='cohorts'&&!inArchiveCohort(r))return false;if(archive&&f.period==='unresolved'&&!needsOutcomeReview(r))return false;if(archive&&f.period==='current'&&r.market_cycle!==CONFIG.currentCycle)return false;if(archive&&f.period==='history'&&!(r.status==='placed'&&CONFIG.historyYears.includes(r.placement_year)&&r.market_cycle!==CONFIG.currentCycle))return false;if(archive&&/^20\d{2}$/.test(f.period||'')&&!(r.status==='placed'&&r.placement_year===Number(f.period)))return false;if(f.track==='marketing_unclassified'&&!(tracks.includes('marketing')&&!tracks.some(t=>['qm','cb','strategy'].includes(t))))return false;if(f.track&& !['all','marketing_unclassified'].includes(f.track)&&!tracks.includes(f.track))return false;if(f.origin&&f.origin!=='all'&&r.origin!==f.origin)return false;if(f.school&&f.school!=='all'&&r.school!==f.school)return false;if(f.job&&f.job!=='all'&&outcome.category!==f.job)return false;if(f.destination&&f.destination!=='all'&&outcome.destination_region!==f.destination)return false;if(f.topic&&f.topic!=='all'&&!r.topics.includes(f.topic))return false;if(f.method&&f.method!=='all'&&!r.methods.includes(f.method))return false;if(f.background&&!backgroundMatches(r,f.background))return false;const text=[r.name,r.school,r.program,r.destination,r.source_reported_placement,...(r.subsequent||[]).map(s=>s.institution||s.employer||s.destination),r.role,r.final_placement?.destination,r.final_placement?.role,r.jmp,...(r.aliases||[]),...r.fields,...r.topics,...r.methods].filter(Boolean).join(' ').toLowerCase();return words.every(w=>text.includes(w))})}
export function summarize(records,basis='final'){const outcomes=placementSummary(records,basis);return {count:records.length,schools:new Set(records.map(r=>r.school)).size,historical:records.filter(r=>['placed','outcome_unknown','deferred'].includes(r.status)).length,...outcomes,onMarket:records.filter(r=>r.status==='on_market'&&r.market_cycle===CONFIG.currentCycle).length,identityKnown:records.filter(r=>r.identity?.chinese_national?.value==='yes'||r.identity?.chinese_heritage?.value==='yes').length}}
export function tally(records,fn){const m=new Map();for(const r of records){const values=fn(r);for(const k of new Set(Array.isArray(values)?values:[values]))if(k)m.set(k,(m.get(k)||0)+1)}return [...m].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))}
export function csvCell(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
